mapper.select:
SELECT SUM(tr.amount) AS total, tr.type AS type, NVL(cg.name, '미분류') AS name FROM transaction tr LEFT JOIN category cg ON tr.category_seq = cg.id WHERE 1=1 and tr.user_seq = #{userSeq, javaType = Long, jdbcType = BIGINT} and tr.transaction_date between #{startDate, javaType = String, jdbcType = VARCHAR} and #{endDate, javaType = String, jdbcType = VARCHAR}
and tr.category_seq IN
#{cid, javaType=Long, jdbcType=BIGINT}
GROUP BY tr.category_seq, tr.type

SELECT SUM(tr.amount) AS total, tr.type AS type, TO_CHAR(tr.transaction_date, 'YYYYMM') AS transaction_date FROM transaction tr LEFT JOIN category cg ON tr.category_seq = cg.id WHERE 1=1 and tr.user_seq = #{userSeq, javaType = Long, jdbcType = BIGINT} and tr.transaction_date between #{startDate, javaType = String, jdbcType = VARCHAR} and #{endDate, javaType = String, jdbcType = VARCHAR}
and tr.category_seq IN
#{cid, javaType=Long, jdbcType=BIGINT}
GROUP BY TO_CHAR(tr.transaction_date, 'YYYYMM'), tr.type
